  1→import React, { useState, useEffect } from 'react';
  2→import { Header, InfiniteAmudScroll, Footer, ParshaNavigation, Toast } from './components';
  3→import { useTikkun } from './hooks/useTikkun';
  4→import { useKeyboardNavigation } from './hooks/useKeyboardNavigation';
  5→import './App.css';
  6→
  7→function App() {
  8→  const {
  9→    currentAmud,
 10→    showNikud,
 11→    wordGap,
 12→    isLoading,
 13→    totalAmudim,
 14→    currentParsha,
 15→    targetLine,
 16→    navigateAmud,
 17→    navigateToParsha,
 18→    navigateParshaDirection,
 19→    toggleNikud,
 20→    adjustWordGap,
 21→    getCurrentAmudData,
 22→    data
 23→  } = useTikkun();
 24→
 25→  const [isNavOpen, setIsNavOpen] = useState(false);
 26→  const [toastMessage, setToastMessage] = useState<string>('');
 27→  const [showToast, setShowToast] = useState(false);
 28→
 29→  const showNavigationFeedback = (message: string) => {
 30→    setToastMessage(message);
 31→    setShowToast(true);
 32→  };
 33→
 34→  // Add keyboard navigation - simple navigation without auto-scroll
 35→  useKeyboardNavigation({
 36→    onPrevious: () => navigateAmud('prev'),
 37→    onNext: () => navigateAmud('next'),
 38→    onPreviousParsha: () => {
 39→      navigateParshaDirection('prev');
 40→      showNavigationFeedback('פרשה קודמת');
 41→    },
 42→    onNextParsha: () => {
 43→      navigateParshaDirection('next');
 44→      showNavigationFeedback('פרשה הבאה');
 45→    },
 46→    onToggleNikud: toggleNikud,
 47→    enabled: !isLoading
 48→  });
 49→
 50→  const currentAmudData = getCurrentAmudData();
 51→
 52→  // Expose navigation functions to window for testing
 53→  useEffect(() => {
 54→    if (typeof window !== 'undefined') {
 55→      (window as any).tikkunNav = {
 56→        navigateToParsha,
 57→        navigateAmud,
 58→        navigateParshaDirection,
 59→        currentParsha,
 60→        currentAmud,
 61→        testNavigation: () => {
 62→          console.log('=== Testing Navigation ===');
 63→          console.log('Current state:', { currentAmud, currentParsha });
 64→          console.log('Available functions: navigateToParsha(sefer, parsha, aliya), navigateAmud(amudNumber), navigateParshaDirection("next"|"prev")');
 65→          console.log('Example: tikkunNav.navigateToParsha("בראשית", "בראשית", 1)');
 66→        }
 67→      };
 68→    }
 69→  }, [navigateToParsha, navigateAmud, navigateParshaDirection, currentParsha, currentAmud]);
 70→
 71→  const handleParshaSelect = (sefer: string, parsha: string, aliya?: number) => {
 72→    console.log('Navigating to:', { sefer, parsha, aliya });
 73→    navigateToParsha(sefer, parsha, aliya);
 74→    setIsNavOpen(false); // Close navigation after selection
 75→    
 76→    // Show feedback
 77→    const aliyaText = aliya ? ` עליה ${aliya}` : '';
 78→    showNavigationFeedback(`נווט ל${parsha}${aliyaText}`);
 79→  };
 80→
 81→  return (
 82→    <div className="App rtl">
 83→      <ParshaNavigation
 84→        isOpen={isNavOpen}
 85→        onToggle={() => setIsNavOpen(!isNavOpen)}
 86→        onParshaSelect={handleParshaSelect}
 87→        currentSefer={currentParsha?.sefer}
 88→        currentParsha={currentParsha?.parsha}
 89→        currentAliya={currentParsha?.aliya}
 90→      />
 91→      <Header
 92→        currentAmud={currentAmud}
 93→        totalAmudim={totalAmudim}
 94→        showNikud={showNikud}
 95→        wordGap={wordGap}
 96→        currentParsha={currentParsha}
 97→        onNavigateAmud={navigateAmud}
 98→        onToggleNikud={toggleNikud}
 99→        onAdjustWordGap={adjustWordGap}
100→      />
101→      <InfiniteAmudScroll
102→        currentAmud={currentAmud}
103→        totalAmudim={totalAmudim}
104→        showNikud={showNikud}
105→        wordGap={wordGap}
106→        isLoading={isLoading}
107→        data={data}
108→        targetLine={targetLine}
109→        onAmudChange={(amud) => navigateAmud(amud)}
110→      />
111→      <Footer />
112→      <Toast
113→        message={toastMessage}
114→        type="success"
115→        show={showToast}
116→        onHide={() => setShowToast(false)}
117→      />
118→    </div>
119→  );
120→}
121→
122→export default App;
