  1→import { useState, useEffect, useCallback } from 'react';
  2→import { Amud } from '../types';
  3→import { 
  4→  findAmudForParshaAliya, 
  5→  getCurrentParshaFromAmud, 
  6→  getNextParshaAliya,
  7→  ParshaLocation 
  8→} from '../utils/navigationUtils';
  9→// We'll lazy load the data to avoid importing a huge file immediately
 10→// import { tikkunData } from '../data/fullTikkunData';
 11→
 12→export interface TikkunState {
 13→  currentAmud: number;
 14→  targetLine?: number; // Add target line for precise scrolling
 15→  showNikud: boolean;
 16→  wordGap: number;
 17→  data: Amud[];
 18→  isLoading: boolean;
 19→  currentParsha?: ParshaLocation;
 20→}
 21→
 22→export const useTikkun = () => {
 23→  const [state, setState] = useState<TikkunState>({
 24→    currentAmud: 1,
 25→    targetLine: undefined,
 26→    showNikud: true,
 27→  wordGap: 6, // legacy default maxGap
 28→    data: [],
 29→    isLoading: true,
 30→    currentParsha: undefined
 31→  });
 32→
 33→  // Load data on mount
 34→  useEffect(() => {
 35→    const loadData = async () => {
 36→      try {
 37→        // Load the sample data
 38→        const { tikkunData } = await import('../data/tikkunData');
 39→        setState(prev => ({ 
 40→          ...prev, 
 41→          data: tikkunData, 
 42→          isLoading: false 
 43→        }));
 44→      } catch (error) {
 45→        console.error('Failed to load Tikkun data:', error);
 46→        setState(prev => ({ ...prev, isLoading: false }));
 47→      }
 48→    };
 49→
 50→    loadData();
 51→  }, []);
 52→
 53→  // Update current parsha when data loads or amud changes
 54→  useEffect(() => {
 55→    if (state.data.length > 0 && !state.currentParsha) {
 56→      console.log('Detecting initial parsha for amud:', state.currentAmud);
 57→      const initialParsha = getCurrentParshaFromAmud(state.data, state.currentAmud);
 58→      console.log('Initial parsha detected:', initialParsha);
 59→      if (initialParsha) {
 60→        setState(prev => ({
 61→          ...prev,
 62→          currentParsha: initialParsha
 63→        }));
 64→      }
 65→    }
 66→  }, [state.data, state.currentAmud, state.currentParsha]);
 67→
 68→  const navigateAmud = useCallback((direction: 'next' | 'prev' | number) => {
 69→    setState(prev => {
 70→      let newAmud = prev.currentAmud;
 71→      
 72→      if (direction === 'next') {
 73→        newAmud = Math.min(prev.currentAmud + 1, prev.data.length);
 74→      } else if (direction === 'prev') {
 75→        newAmud = Math.max(prev.currentAmud - 1, 1);
 76→      } else if (typeof direction === 'number') {
 77→        newAmud = Math.max(1, Math.min(direction, prev.data.length));
 78→      }
 79→      
 80→      // Update current parsha when amud changes
 81→      const newParsha = getCurrentParshaFromAmud(prev.data, newAmud);
 82→      
 83→      return { 
 84→        ...prev, 
 85→        currentAmud: newAmud,
 86→        targetLine: undefined, // Clear target line for regular amud navigation
 87→        currentParsha: newParsha || prev.currentParsha
 88→      };
 89→    });
 90→  }, []);
 91→
 92→  const navigateToParsha = useCallback((sefer: string, parsha: string, aliya?: number) => {
 93→    setState(prev => {
 94→      console.log('Attempting to navigate to:', { sefer, parsha, aliya });
 95→      const location = findAmudForParshaAliya(prev.data, sefer, parsha, aliya);
 96→      console.log('Found location:', location);
 97→      
 98→      if (location) {
 99→        const newParsha: ParshaLocation = { sefer, parsha, aliya };
100→        console.log('Navigating to amud:', location.amud, 'line:', location.line);
101→        return {
102→          ...prev,
103→          currentAmud: location.amud,
104→          targetLine: location.line,
105→          currentParsha: newParsha
106→        };
107→      }
108→      console.log('Location not found');
109→      return prev;
110→    });
111→  }, []);
112→
113→  const navigateParshaDirection = useCallback((direction: 'next' | 'prev') => {
114→    setState(prev => {
115→      if (!prev.currentParsha) return prev;
116→      
117→      const nextParsha = getNextParshaAliya(
118→        prev.currentParsha.sefer,
119→        prev.currentParsha.parsha,
120→        prev.currentParsha.aliya,
121→        direction
122→      );
123→      
124→      if (nextParsha) {
125→        const location = findAmudForParshaAliya(prev.data, nextParsha.sefer, nextParsha.parsha, nextParsha.aliya);
126→        if (location) {
127→          return {
128→            ...prev,
129→            currentAmud: location.amud,
130→            currentParsha: nextParsha
131→          };
132→        }
133→      }
134→      
135→      return prev;
136→    });
137→  }, []);
138→
139→  const toggleNikud = useCallback(() => {
140→    setState(prev => ({ ...prev, showNikud: !prev.showNikud }));
141→  }, []);
142→
143→  const adjustWordGap = useCallback((change: number) => {
144→    setState(prev => ({
145→      ...prev,
146→  wordGap: Math.max(1, Math.min(6, prev.wordGap + change)) // legacy min = 1
147→    }));
148→  }, []);
149→
150→  const getCurrentAmudData = useCallback((): Amud | null => {
151→    const amudData = state.data.find(amud => amud.amud === state.currentAmud);
152→    return amudData || null;
153→  }, [state.data, state.currentAmud]);
154→
155→  return {
156→    ...state,
157→    navigateAmud,
158→    navigateToParsha,
159→    navigateParshaDirection,
160→    toggleNikud,
161→    adjustWordGap,
162→    getCurrentAmudData,
163→    totalAmudim: state.data.length,
164→    data: state.data // Expose data for infinite scroll
165→  };
166→};
