 1→import { useEffect } from 'react';
 2→
 3→interface UseKeyboardNavigationProps {
 4→  onPrevious: () => void;
 5→  onNext: () => void;
 6→  onToggleNikud: () => void;
 7→  onPreviousParsha?: () => void;
 8→  onNextParsha?: () => void;
 9→  enabled?: boolean;
10→}
11→
12→export const useKeyboardNavigation = ({
13→  onPrevious,
14→  onNext,
15→  onToggleNikud,
16→  onPreviousParsha,
17→  onNextParsha,
18→  enabled = true
19→}: UseKeyboardNavigationProps) => {
20→  useEffect(() => {
21→    if (!enabled) return;
22→
23→    const handleKeyPress = (event: KeyboardEvent) => {
24→      // Don't trigger if user is typing in an input field
25→      if (event.target instanceof HTMLInputElement || 
26→          event.target instanceof HTMLTextAreaElement) {
27→        return;
28→      }
29→
30→      switch (event.key) {
31→        case 'ArrowLeft':
32→        case 'h':
33→          event.preventDefault();
34→          onPrevious();
35→          break;
36→        case 'ArrowRight':
37→        case 'l':
38→          event.preventDefault();
39→          onNext();
40→          break;
41→        case 'ArrowUp':
42→        case 'k':
43→          if (onPreviousParsha) {
44→            event.preventDefault();
45→            onPreviousParsha();
46→          }
47→          break;
48→        case 'ArrowDown':
49→        case 'j':
50→          if (onNextParsha) {
51→            event.preventDefault();
52→            onNextParsha();
53→          }
54→          break;
55→        case 'n':
56→        case 'N':
57→          event.preventDefault();
58→          onToggleNikud();
59→          break;
60→        case ' ':
61→          event.preventDefault();
62→          onToggleNikud();
63→          break;
64→      }
65→    };
66→
67→    document.addEventListener('keydown', handleKeyPress);
68→
69→    return () => {
70→      document.removeEventListener('keydown', handleKeyPress);
71→    };
72→  }, [onPrevious, onNext, onToggleNikud, onPreviousParsha, onNextParsha, enabled]);
73→};
