  1→import { Amud, Meta } from '../types';
  2→import { aliyos, parshios, seforim } from '../data/parshadata';
  3→
  4→export interface ParshaLocation {
  5→  sefer: string;
  6→  parsha: string;
  7→  aliya?: number;
  8→}
  9→
 10→export interface AmudLocation {
 11→  amud: number;
 12→  line?: number;
 13→}
 14→
 15→/**
 16→ * Parse parsha range string like "16:1 16:17" to get start and end positions
 17→ */
 18→function parseParshaRange(range: string): { start: { perek: number; pasuk: number }, end: { perek: number; pasuk: number } } {
 19→  const [startStr, endStr] = range.split(' ');
 20→  const [startPerek, startPasuk] = startStr.split(':').map(Number);
 21→  const [endPerek, endPasuk] = endStr.split(':').map(Number);
 22→  
 23→  return {
 24→    start: { perek: startPerek, pasuk: startPasuk },
 25→    end: { perek: endPerek, pasuk: endPasuk }
 26→  };
 27→}
 28→
 29→/**
 30→ * Convert sefer name to sefer number
 31→ */
 32→function getSeferNumber(seferName: string): number {
 33→  const seferIndex = seforim.indexOf(seferName);
 34→  return seferIndex >= 0 ? seferIndex + 1 : 1;
 35→}
 36→
 37→/**
 38→ * Check if a given position (perek/pasuk) falls within a range
 39→ */
 40→function isPositionInRange(
 41→  position: { perek: number; pasuk: number },
 42→  range: { start: { perek: number; pasuk: number }, end: { perek: number; pasuk: number } }
 43→): boolean {
 44→  if (position.perek < range.start.perek || position.perek > range.end.perek) {
 45→    return false;
 46→  }
 47→  
 48→  if (position.perek === range.start.perek && position.pasuk < range.start.pasuk) {
 49→    return false;
 50→  }
 51→  
 52→  if (position.perek === range.end.perek && position.pasuk > range.end.pasuk) {
 53→    return false;
 54→  }
 55→  
 56→  return true;
 57→}
 58→
 59→/**
 60→ * Find the amud number that contains the start of a specific parsha/aliya
 61→ */
 62→export function findAmudForParshaAliya(
 63→  data: Amud[], 
 64→  sefer: string, 
 65→  parsha: string, 
 66→  aliya?: number
 67→): AmudLocation | null {
 68→  const seferNumber = getSeferNumber(sefer);
 69→  
 70→  // Get the aliya range if specified
 71→  let targetRange: { start: { perek: number; pasuk: number }, end: { perek: number; pasuk: number } } | null = null;
 72→  
 73→  if (aliya && aliyos[parsha as keyof typeof aliyos]) {
 74→    const aliyaData = aliyos[parsha as keyof typeof aliyos] as any;
 75→    const aliyaKey = aliya.toString();
 76→    if (aliyaData[aliyaKey]) {
 77→      targetRange = parseParshaRange(aliyaData[aliyaKey]);
 78→    }
 79→  } else if (aliyos[parsha as keyof typeof aliyos]) {
 80→    // If no specific aliya requested, use the first aliya of the parsha
 81→    const aliyaData = aliyos[parsha as keyof typeof aliyos] as any;
 82→    if (aliyaData['1']) {
 83→      targetRange = parseParshaRange(aliyaData['1']);
 84→    }
 85→  }
 86→
 87→  if (!targetRange) {
 88→    console.log('No range found for', { sefer, parsha, aliya });
 89→    return null;
 90→  }
 91→
 92→  // Find the first amud that contains the target position
 93→  for (const amud of data) {
 94→    for (let lineIndex = 0; lineIndex < amud.lines.length; lineIndex++) {
 95→      const line = amud.lines[lineIndex];
 96→      
 97→      // Check if this line has metadata for our target sefer
 98→      for (const meta of line.meta) {
 99→        if (hasCompleteMeta(meta) && meta.sefer === seferNumber) {
100→          // Check if this position matches our target range start
101→          if (meta.perek === targetRange.start.perek && meta.pasuk === targetRange.start.pasuk) {
102→            return { amud: amud.amud, line: lineIndex + 1 };
103→          }
104→          
105→          // Also check if we're close to the start (within the range)
106→          if (isPositionInRange({ perek: meta.perek, pasuk: meta.pasuk }, targetRange)) {
107→            return { amud: amud.amud, line: lineIndex + 1 };
108→          }
109→        }
110→      }
111→    }
112→  }
113→  
114→  console.log('No amud found for parsha/aliya', { sefer, parsha, aliya, targetRange });
115→  return null;
116→}
117→
118→/**
119→ * Find the current parsha/aliya based on the current amud and position
120→ */
121→export function getCurrentParshaFromAmud(
122→  data: Amud[],
123→  currentAmud: number,
124→  lineNumber?: number
125→): ParshaLocation | null {
126→  const amud = data.find(a => a.amud === currentAmud);
127→  if (!amud) return null;
128→  
129→  // Try to find a line with complete meta data
130→  let targetLine = null;
131→  if (lineNumber && lineNumber <= amud.lines.length) {
132→    targetLine = amud.lines[lineNumber - 1];
133→  }
134→  
135→  // If the specified line doesn't have good meta, search for the first line with complete meta
136→  if (!targetLine || !targetLine.meta.length || !hasCompleteMeta(targetLine.meta[0])) {
137→    targetLine = amud.lines.find(line => 
138→      line.meta.length > 0 && hasCompleteMeta(line.meta[0])
139→    );
140→  }
141→  
142→  if (!targetLine || !targetLine.meta.length) return null;
143→  
144→  const meta = targetLine.meta[0];
145→  const seferName = seforim[meta.sefer - 1];
146→  if (!seferName) return null;
147→  
148→  // Find which parsha this position belongs to
149→  const parshaSefaram = parshios[seferName as keyof typeof parshios];
150→  if (!parshaSefaram) return null;
151→  
152→  // Check each parsha to see if our position falls within it
153→  for (const parsha of parshaSefaram) {
154→    const aliyaData = aliyos[parsha as keyof typeof aliyos] as any;
155→    if (!aliyaData) continue;
156→    
157→    // Check all aliyot in this parsha
158→    for (let aliyaNum = 1; aliyaNum <= 8; aliyaNum++) {
159→      const aliyaKey = aliyaNum.toString();
160→      if (aliyaData[aliyaKey]) {
161→        const range = parseParshaRange(aliyaData[aliyaKey]);
162→        if (isPositionInRange({ perek: meta.perek, pasuk: meta.pasuk }, range)) {
163→          return {
164→            sefer: seferName,
165→            parsha: parsha,
166→            aliya: aliyaNum
167→          };
168→        }
169→      }
170→    }
171→  }
172→  
173→  // If we couldn't find a specific aliya, return the first parsha of the sefer as fallback
174→  return {
175→    sefer: seferName,
176→    parsha: parshaSefaram[0],
177→    aliya: undefined
178→  };
179→}
180→
181→/**
182→ * Check if meta data is complete (has all required fields)
183→ */
184→function hasCompleteMeta(meta: any): boolean {
185→  return meta && meta.sefer && meta.perek !== null && meta.pasuk !== null;
186→}
187→
188→/**
189→ * Get the next/previous parsha/aliya
190→ */
191→export function getNextParshaAliya(
192→  currentSefer: string,
193→  currentParsha: string,
194→  currentAliya?: number,
195→  direction: 'next' | 'prev' = 'next'
196→): ParshaLocation | null {
197→  const seferParshaList = parshios[currentSefer as keyof typeof parshios];
198→  if (!seferParshaList) return null;
199→  
200→  const currentParshaIndex = seferParshaList.indexOf(currentParsha);
201→  if (currentParshaIndex === -1) return null;
202→  
203→  // If we have an aliya, try to navigate within the same parsha first
204→  if (currentAliya) {
205→    const aliyaData = aliyos[currentParsha as keyof typeof aliyos] as any;
206→    if (aliyaData) {
207→      const nextAliya = direction === 'next' ? currentAliya + 1 : currentAliya - 1;
208→      const nextAliyaKey = nextAliya.toString();
209→      
210→      if (nextAliya >= 1 && nextAliya <= 8 && aliyaData[nextAliyaKey]) {
211→        return {
212→          sefer: currentSefer,
213→          parsha: currentParsha,
214→          aliya: nextAliya
215→        };
216→      }
217→    }
218→  }
219→  
220→  // Navigate to next/previous parsha
221→  const nextParshaIndex = direction === 'next' ? currentParshaIndex + 1 : currentParshaIndex - 1;
222→  
223→  if (nextParshaIndex >= 0 && nextParshaIndex < seferParshaList.length) {
224→    const nextParsha = seferParshaList[nextParshaIndex];
225→    return {
226→      sefer: currentSefer,
227→      parsha: nextParsha,
228→      aliya: direction === 'next' ? 1 : undefined // Start at first aliya for next parsha
229→    };
230→  }
231→  
232→  // Navigate to next/previous sefer
233→  const currentSeferIndex = seforim.indexOf(currentSefer);
234→  const nextSeferIndex = direction === 'next' ? currentSeferIndex + 1 : currentSeferIndex - 1;
235→  
236→  if (nextSeferIndex >= 0 && nextSeferIndex < seforim.length) {
237→    const nextSefer = seforim[nextSeferIndex];
238→    const nextSeferParshaList = parshios[nextSefer as keyof typeof parshios];
239→    if (nextSeferParshaList && nextSeferParshaList.length > 0) {
240→      const nextParsha = direction === 'next' ? nextSeferParshaList[0] : nextSeferParshaList[nextSeferParshaList.length - 1];
241→      return {
242→        sefer: nextSefer,
243→        parsha: nextParsha,
244→        aliya: direction === 'next' ? 1 : undefined
245→      };
246→    }
247→  }
248→  
249→  return null;
250→}
251→
252→/**
253→ * Get all aliyot for a specific parsha
254→ */
255→export function getAliyotForParsha(parsha: string): Array<{ number: number; name: string; range: string }> {
256→  const aliyaData = aliyos[parsha as keyof typeof aliyos] as any;
257→  if (!aliyaData) return [];
258→  
259→  const result = [];
260→  for (let i = 1; i <= 8; i++) {
261→    const aliyaKey = i.toString();
262→    if (aliyaData[aliyaKey]) {
263→      result.push({
264→        number: i,
265→        name: ['ראשון', 'שני', 'שלישי', 'רביעי', 'חמישי', 'שישי', 'שביעי', 'מפטיר'][i - 1],
266→        range: aliyaData[aliyaKey]
267→      });
268→    }
269→  }
270→  
271→  return result;
272→}
