  1→import React, { useEffect, useRef, useState, useCallback } from 'react';
  2→import { Amud } from '../../types';
  3→import { TextLine } from '../TextLine/TextLine';
  4→import { LoadingSpinner } from '../LoadingSpinner/LoadingSpinner';
  5→import './InfiniteAmudScroll.css';
  6→
  7→interface InfiniteAmudScrollProps {
  8→  currentAmud: number;
  9→  totalAmudim: number;
 10→  showNikud: boolean;
 11→  wordGap: number;
 12→  isLoading: boolean;
 13→  data: Amud[];
 14→  targetLine?: number; // Add target line for precise scrolling
 15→  onAmudChange: (amud: number) => void;
 16→}
 17→
 18→export const InfiniteAmudScroll: React.FC<InfiniteAmudScrollProps> = ({
 19→  currentAmud,
 20→  totalAmudim,
 21→  showNikud,
 22→  wordGap,
 23→  isLoading,
 24→  data,
 25→  targetLine,
 26→  onAmudChange
 27→}) => {
 28→  const containerRef = useRef<HTMLDivElement>(null);
 29→  const isScrollingRef = useRef(false);
 30→  const scrollTimeoutRef = useRef<number>();
 31→
 32→  // Function to scroll to a specific amud and line
 33→  const scrollToAmudAndLine = useCallback((amudNumber: number, lineNumber?: number) => {
 34→    if (!containerRef.current) return;
 35→
 36→    // Clear any existing scroll timeout
 37→    if (scrollTimeoutRef.current) {
 38→      window.clearTimeout(scrollTimeoutRef.current);
 39→    }
 40→
 41→    // Set scrolling flag to prevent intersection observer interference
 42→    isScrollingRef.current = true;
 43→
 44→    // Find the target amud element
 45→    const amudElement = containerRef.current.querySelector(`[data-amud="${amudNumber}"]`);
 46→    if (!amudElement) {
 47→      console.log('Amud element not found:', amudNumber);
 48→      isScrollingRef.current = false;
 49→      return;
 50→    }
 51→
 52→    let targetElement = amudElement;
 53→
 54→    // If a specific line is requested, find that line within the amud
 55→    if (lineNumber) {
 56→      const lineElement = amudElement.querySelector(`[data-line="${lineNumber}"]`);
 57→      if (lineElement) {
 58→        targetElement = lineElement;
 59→        console.log('Scrolling to amud', amudNumber, 'line', lineNumber);
 60→      } else {
 61→        console.log('Line not found, scrolling to amud start:', lineNumber);
 62→      }
 63→    }
 64→
 65→    // Scroll to the target element immediately for fast navigation
 66→    targetElement.scrollIntoView({
 67→      behavior: 'auto', // Changed from 'smooth' to 'auto' for instant navigation
 68→      block: 'center',
 69→      inline: 'nearest'
 70→    });
 71→
 72→    // Reset scrolling flag after a short delay
 73→    scrollTimeoutRef.current = window.setTimeout(() => {
 74→      isScrollingRef.current = false;
 75→    }, 150);
 76→  }, []);
 77→
 78→  // Effect to handle scrolling when currentAmud or targetLine changes
 79→  useEffect(() => {
 80→    if (currentAmud && data.length > 0) {
 81→      // Use requestAnimationFrame for better performance
 82→      requestAnimationFrame(() => {
 83→        scrollToAmudAndLine(currentAmud, targetLine);
 84→      });
 85→    }
 86→  }, [currentAmud, targetLine, data.length, scrollToAmudAndLine]);
 87→
 88→  // Intersection Observer to detect which amud is currently visible
 89→  useEffect(() => {
 90→    if (!containerRef.current || isLoading) return;
 91→
 92→    const observer = new IntersectionObserver(
 93→      (entries) => {
 94→        // Don't trigger amud changes if we're currently scrolling programmatically
 95→        if (isScrollingRef.current) return;
 96→        
 97→        entries.forEach((entry) => {
 98→          if (entry.isIntersecting && entry.intersectionRatio > 0.6) {
 99→            const amudNumber = parseInt(entry.target.getAttribute('data-amud') || '0');
100→            if (amudNumber && amudNumber !== currentAmud) {
101→              onAmudChange(amudNumber);
102→            }
103→          }
104→        });
105→      },
106→      {
107→        root: null, // Use viewport as root
108→        rootMargin: '-40% 0px -40% 0px', // Only trigger when amud is well centered
109→        threshold: [0.6]
110→      }
111→    );
112→
113→    // Observe all amud elements
114→    const amudElements = containerRef.current.querySelectorAll('[data-amud]');
115→    amudElements.forEach((element) => observer.observe(element));
116→
117→    return () => observer.disconnect();
118→  }, [data, currentAmud, onAmudChange, isLoading]);
119→
120→  if (isLoading) {
121→    return (
122→      <div className="infinite-amud-scroll loading">
123→        <LoadingSpinner message="טוען עמודים..." size="large" />
124→      </div>
125→    );
126→  }
127→
128→  // Cleanup timeout on unmount
129→  useEffect(() => {
130→    return () => {
131→      if (scrollTimeoutRef.current) {
132→        window.clearTimeout(scrollTimeoutRef.current);
133→      }
134→    };
135→  }, []);
136→
137→  // Check if amud 78 is in the data to apply special styling
138→  const hasAmud78 = data.some(amud => amud.amud === 78);
139→
140→  return (
141→    <div className={`infinite-amud-scroll ${hasAmud78 ? 'has-amud-78' : ''}`} ref={containerRef}>
142→      {data.map((amudData) => (
143→        <div 
144→          key={amudData.amud} 
145→          className={`amud-display ${amudData.amud === currentAmud ? 'current' : ''}`}
146→          data-amud={amudData.amud}
147→        >
148→          <div className="amud-content">
149→            {amudData.lines.map((line) => (
150→              <div key={line.number} data-line={line.number}>
151→                <TextLine
152→                  line={line}
153→                  showNikud={showNikud}
154→                  wordGap={amudData.amud === 78 ? 0 : wordGap}
155→                />
156→              </div>
157→            ))}
158→          </div>
159→        </div>
160→      ))}
161→    </div>
162→  );
163→};
